14	const SVG_CONTENT_TYPE = "image/svg+xml";
15	const ALLOWED_COMPANY_LOGO_CONTENT_TYPES = new Set([
16	  "image/png",
17	  "image/jpeg",
18	  "image/jpg",
19	  "image/webp",
20	  "image/gif",
21	  SVG_CONTENT_TYPE,
22	]);
