88	export function assetRoutes(db: Db, storage: StorageService) {
89	  const router = Router();
90	  const svc = assetService(db);
91	  const assetUpload = multer({
92	    storage: multer.memoryStorage(),
93	    limits: { fileSize: MAX_ATTACHMENT_BYTES, files: 1 },
94	  });
95	  const companyLogoUpload = multer({
96	    storage: multer.memoryStorage(),
97	    limits: { fileSize: MAX_ATTACHMENT_BYTES, files: 1 },
98	  });
99	
100	  async function runSingleFileUpload(
101	    upload: ReturnType<typeof multer>,
102	    req: Request,
103	    res: Response,
104	  ) {
105	    await new Promise<void>((resolve, reject) => {
106	      upload.single("file")(req, res, (err: unknown) => {
107	        if (err) reject(err);
108	        else resolve();
109	      });
110	    });
111	  }
112	
113	  // ---------------------------------------------------------------------------
114	  // POST /companies/:companyId/assets/images
115	  // TODO(cloudflare): file upload requires R2 multipart
116	  // ---------------------------------------------------------------------------
117	  router.post("/companies/:companyId/assets/images", async (req, res) => {
118	    const companyId = req.params.companyId as string;
119	    assertCompanyAccess(req, companyId);
120	
121	    try {
122	      await runSingleFileUpload(assetUpload, req, res);
123	    } catch (err) {
124	      if (err instanceof multer.MulterError) {
125	        if (err.code === "LIMIT_FILE_SIZE") {
126	          res.status(422).json({ error: `File exceeds ${MAX_ATTACHMENT_BYTES} bytes` });
127	          return;
128	        }
129	        res.status(400).json({ error: err.message });
130	        return;
131	      }
132	      throw err;
133	    }
134	
135	    const file = (req as Request & { file?: { mimetype: string; buffer: Buffer; originalname: string } }).file;
136	    if (!file) {
137	      res.status(400).json({ error: "Missing file field 'file'" });
138	      return;
139	    }
140	
141	    const parsedMeta = createAssetImageMetadataSchema.safeParse(req.body ?? {});
142	    if (!parsedMeta.success) {
143	      res.status(400).json({ error: "Invalid image metadata", details: parsedMeta.error.issues });
144	      return;
145	    }
146	
147	    const namespaceSuffix = parsedMeta.data.namespace ?? "general";
148	    const contentType = (file.mimetype || "").toLowerCase();
149	    if (contentType !== SVG_CONTENT_TYPE && !isAllowedContentType(contentType)) {
150	      res.status(422).json({ error: `Unsupported file type: ${contentType || "unknown"}` });
151	      return;
152	    }
153	    let fileBody = file.buffer;
154	    if (contentType === SVG_CONTENT_TYPE) {
155	      const sanitized = sanitizeSvgBuffer(file.buffer);
156	      if (!sanitized || sanitized.length <= 0) {
157	        res.status(422).json({ error: "SVG could not be sanitized" });
158	        return;
159	      }
160	      fileBody = sanitized;
161	    }
162	    if (fileBody.length <= 0) {
163	      res.status(422).json({ error: "Image is empty" });
164	      return;
165	    }
166	
167	    const actor = getActorInfo(req);
168	    const stored = await storage.putFile({
169	      companyId,
170	      namespace: `assets/${namespaceSuffix}`,
171	      originalFilename: file.originalname || null,
172	      contentType,
173	      body: fileBody,
174	    });
175	
176	    const asset = await svc.create(companyId, {
177	      provider: stored.provider,
178	      objectKey: stored.objectKey,
179	      contentType: stored.contentType,
180	      byteSize: stored.byteSize,
181	      sha256: stored.sha256,
182	      originalFilename: stored.originalFilename,
183	      createdByAgentId: actor.agentId,
184	      createdByUserId: actor.actorType === "user" ? actor.actorId : null,
185	    });
186	
187	    await logActivity(db, {
188	      companyId,
189	      actorType: actor.actorType,
190	      actorId: actor.actorId,
191	      agentId: actor.agentId,
192	      runId: actor.runId,
193	      action: "asset.created",
194	      entityType: "asset",
195	      entityId: asset.id,
196	      details: {
197	        originalFilename: asset.originalFilename,
198	        contentType: asset.contentType,
199	        byteSize: asset.byteSize,
200	      },
201	    });
202	
203	    res.status(201).json({
204	      assetId: asset.id,
205	      companyId: asset.companyId,
206	      provider: asset.provider,
207	      objectKey: asset.objectKey,
208	      contentType: asset.contentType,
209	      byteSize: asset.byteSize,
210	      sha256: asset.sha256,
211	      originalFilename: asset.originalFilename,
212	      createdByAgentId: asset.createdByAgentId,
213	      createdByUserId: asset.createdByUserId,
214	      createdAt: asset.createdAt,
215	      updatedAt: asset.updatedAt,
216	      contentPath: `/api/assets/${asset.id}/content`,
217	    });
218	  });
219	
220	  // ---------------------------------------------------------------------------
221	  // POST /companies/:companyId/logo
222	  // TODO(cloudflare): file upload requires R2 multipart
223	  // ---------------------------------------------------------------------------
224	  router.post("/companies/:companyId/logo", async (req, res) => {
225	    const companyId = req.params.companyId as string;
226	    assertCompanyAccess(req, companyId);
227	
228	    try {
229	      await runSingleFileUpload(companyLogoUpload, req, res);
230	    } catch (err) {
231	      if (err instanceof multer.MulterError) {
232	        if (err.code === "LIMIT_FILE_SIZE") {
233	          res.status(422).json({ error: `Image exceeds ${MAX_ATTACHMENT_BYTES} bytes` });
234	          return;
235	        }
236	        res.status(400).json({ error: err.message });
237	        return;
238	      }
239	      throw err;
240	    }
241	
242	    const file = (req as Request & { file?: { mimetype: string; buffer: Buffer; originalname: string } }).file;
243	    if (!file) {
244	      res.status(400).json({ error: "Missing file field 'file'" });
245	      return;
246	    }
247	
248	    const contentType = (file.mimetype || "").toLowerCase();
249	    if (!ALLOWED_COMPANY_LOGO_CONTENT_TYPES.has(contentType)) {
250	      res.status(422).json({ error: `Unsupported image type: ${contentType || "unknown"}` });
251	      return;
252	    }
253	
254	    let fileBody = file.buffer;
255	    if (contentType === SVG_CONTENT_TYPE) {
256	      const sanitized = sanitizeSvgBuffer(file.buffer);
257	      if (!sanitized || sanitized.length <= 0) {
258	        res.status(422).json({ error: "SVG could not be sanitized" });
259	        return;
260	      }
261	      fileBody = sanitized;
262	    }
263	
264	    if (fileBody.length <= 0) {
265	      res.status(422).json({ error: "Image is empty" });
266	      return;
267	    }
268	
269	    const actor = getActorInfo(req);
270	    const stored = await storage.putFile({
271	      companyId,
272	      namespace: "assets/companies",
273	      originalFilename: file.originalname || null,
274	      contentType,
275	      body: fileBody,
276	    });
277	
278	    const asset = await svc.create(companyId, {
279	      provider: stored.provider,
280	      objectKey: stored.objectKey,
281	      contentType: stored.contentType,
282	      byteSize: stored.byteSize,
283	      sha256: stored.sha256,
284	      originalFilename: stored.originalFilename,
285	      createdByAgentId: actor.agentId,
286	      createdByUserId: actor.actorType === "user" ? actor.actorId : null,
287	    });
288	
289	    await logActivity(db, {
290	      companyId,
291	      actorType: actor.actorType,
292	      actorId: actor.actorId,
293	      agentId: actor.agentId,
294	      runId: actor.runId,
295	      action: "asset.created",
296	      entityType: "asset",
297	      entityId: asset.id,
298	      details: {
299	        originalFilename: asset.originalFilename,
300	        contentType: asset.contentType,
301	        byteSize: asset.byteSize,
302	        namespace: "assets/companies",
303	      },
304	    });
305	
306	    res.status(201).json({
307	      assetId: asset.id,
308	      companyId: asset.companyId,
309	      provider: asset.provider,
310	      objectKey: asset.objectKey,
311	      contentType: asset.contentType,
312	      byteSize: asset.byteSize,
313	      sha256: asset.sha256,
314	      originalFilename: asset.originalFilename,
315	      createdByAgentId: asset.createdByAgentId,
316	      createdByUserId: asset.createdByUserId,
317	      createdAt: asset.createdAt,
318	      updatedAt: asset.updatedAt,
319	      contentPath: `/api/assets/${asset.id}/content`,
320	    });
321	  });
322	
323	  // ---------------------------------------------------------------------------
324	  // GET /assets/:assetId/content — streaming response
325	  // ---------------------------------------------------------------------------
326	
327	  const getAssetContent: Handler = async (ctx) => {
328	    const assetId = ctx.param("assetId");
329	    if (!assetId) return Response.json({ error: "Missing assetId" }, { status: 400 });
330	    const asset = await svc.getById(assetId);
331	    if (!asset) {
332	      return Response.json({ error: "Asset not found" }, { status: 404 });
333	    }
334	    if (!ctx.actor) {
335	      return Response.json({ error: "Authentication required" }, { status: 401 });
336	    }
337	
338	    const object = await storage.getObject(asset.companyId, asset.objectKey);
339	    const responseContentType = asset.contentType || object.contentType || "application/octet-stream";
340	    const filename = asset.originalFilename ?? "asset";
341	
342	    const headers: Record<string, string> = {
343	      "Content-Type": responseContentType,
344	      "Content-Length": String(asset.byteSize || object.contentLength || 0),
345	      "Cache-Control": "private, max-age=60",
346	      "X-Content-Type-Options": "nosniff",
347	      "Content-Disposition": `inline; filename="${filename.replaceAll('"', '')}"`,
348	    };
349	    if (responseContentType === SVG_CONTENT_TYPE) {
350	      headers["Content-Security-Policy"] = "sandbox; default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'";
351	    }
352	
353	    return new Response(object.stream as unknown as ReadableStream, { headers });
354	  };
355	
356	  router.get("/assets/:assetId/content", expressHandler(getAssetContent, { db, storage }));
357	
358	  return router;
359	}
